package io.github.vitoosh.vitquest.core.data.seed

import kotlinx.serialization.Serializable

// Shapes of app/src/main/assets/seed/*.json (generated by tools/seed/*.py).

@Serializable
data class FoodSeedFile(val version: Int, val foods: List<FoodSeed>)

@Serializable
data class FoodSeed(
    val key: String,
    val nameId: String,
    val nameEn: String,
    val category: String,
    val kcal: Double,
    val protein: Double? = null,
    val carbs: Double? = null,
    val fat: Double? = null,
    val source: String,
    val servings: List<ServingSeed>,
)

@Serializable
data class ServingSeed(val labelId: String, val labelEn: String, val grams: Double)

@Serializable
data class RecipeSeedFile(val version: Int, val recipes: List<RecipeSeed>)

@Serializable
data class RecipeSeed(
    val key: String,
    val nameId: String,
    val nameEn: String,
    val descriptionId: String,
    val descriptionEn: String,
    val servings: Int,
    val prep: Int,
    val cook: Int,
    val tags: List<String>,
    val ingredients: List<IngredientSeed>,
    val stepsId: List<String>,
    val stepsEn: List<String>,
)

@Serializable
data class IngredientSeed(
    /** Key of a food in foods.json; its per-100 g values give the ingredient's nutrients. */
    val food: String,
    val grams: Double,
    val quantity: Double,
    val unitId: String,
    val unitEn: String,
    val nameId: String,
    val nameEn: String,
    val substituteId: String? = null,
    val substituteEn: String? = null,
)
